  if (coffsets == NULL) {
    fprintf(stderr, "Error: cannot get the offset for chunk %d for the frame\n", nchunk);
    return -3;
  }

  int rc = blosc_getitem(coffsets, nchunk, 1, &offset);
  if (rc < 0) {
